//! ↩️ create-image leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfImage;
use crate::artifacts::gltf::schema::mutations::create_image::mutation::{validate, GltfCreateImagePayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{images_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.create-image.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfCreateImageInverseOperation { Insert { position: usize, item: GltfImage }, Delete { index: usize, removed: GltfImage }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfCreateImageInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfCreateImagePayload, pub operation: GltfCreateImageInverseOperation }
async fn operation(payload: &GltfCreateImagePayload, base: &GltfSnapshot) -> GltfCreateImageInverseOperation { GltfCreateImageInverseOperation::Delete { index: payload.position, removed: GltfImage::default() } }
async fn touched_paths(payload: &GltfCreateImagePayload) -> Vec<String> { vec![format!("document/images/{}", payload.position)] }
pub async fn validate_inverse(inverse: &GltfCreateImageInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub async fn apply_inverse(inverse: &GltfCreateImageInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfCreateImageInverseOperation::Insert { position, .. } if *position > after.document.images.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/images", "position must be within the collection")), GltfCreateImageInverseOperation::Delete { index, .. } if *index >= after.document.images.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/images", "index must address an item")), GltfCreateImageInverseOperation::Move { index, position } if *index >= after.document.images.len() || *position >= after.document.images.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/images", "indices must address items")), GltfCreateImageInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.images.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.images.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/images", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfCreateImageInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Images, &Change::Insert(*position))?; next.document.images.insert(*position, item.clone());  }, GltfCreateImageInverseOperation::Delete { index, .. } => { images_op(&mut next, GltfTopLevelFamily::Images, *index, None, None)?;  }, GltfCreateImageInverseOperation::Move { index, position } => { images_op(&mut next, GltfTopLevelFamily::Images, *index, Some(*position), None)?;  }, GltfCreateImageInverseOperation::Reorder { order } => { images_op(&mut next, GltfTopLevelFamily::Images, order[0], None, Some(order))?;  } } Ok(next) }
pub async fn encode(inverse: &GltfCreateImageInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub async fn derive(payload: &GltfCreateImagePayload, base: &GltfSnapshot) -> Result<GltfCreateImageInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfCreateImageInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
